'use client';

import * as React from 'react';
import { motion, type HTMLMotionProps } from 'framer-motion';
import { cn } from '@/lib/utils';

export type ButtonVariant = 'default' | 'secondary' | 'outline' | 'ghost' | 'subtle' | 'tactile' | 'recessed';
export type ButtonSize = 'sm' | 'md' | 'lg';

export interface ButtonProps extends Omit<HTMLMotionProps<'button'>, 'children'> {
  children?: React.ReactNode;
  variant?: ButtonVariant;
  size?: ButtonSize;
  isLoading?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
}

const variantStyles: Record<ButtonVariant, string> = {
  default:
    'bg-primary text-primary-foreground hover:opacity-90 active:opacity-95 shadow-2xs font-medium',
  secondary:
    'bg-card border border-border text-text-primary hover:bg-accent hover:border-foreground/20 font-medium shadow-2xs',
  outline:
    'bg-transparent border border-border text-text-primary hover:bg-secondary/60 hover:border-foreground/20 font-medium',
  ghost:
    'bg-transparent text-text-secondary hover:text-text-primary hover:bg-secondary/60 font-medium',
  subtle:
    'bg-secondary/80 border border-border/60 text-text-primary hover:bg-secondary font-medium',
  tactile:
    'tactile-btn bg-card border border-border/80 text-text-primary font-medium hover:border-foreground/30',
  recessed:
    'tactile-well bg-secondary text-text-secondary hover:text-text-primary font-medium active:translate-y-[0.5px]',
};

const sizeStyles: Record<ButtonSize, string> = {
  sm: 'px-3 py-1.5 text-xs rounded-lg gap-1.5 h-8',
  md: 'px-4 py-2 text-ui rounded-lg gap-2 h-9',
  lg: 'px-5 py-2.5 text-ui rounded-xl gap-2.5 h-11',
};

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant = 'default',
      size = 'md',
      isLoading = false,
      leftIcon,
      rightIcon,
      children,
      disabled,
      ...props
    },
    ref
  ) => {
    const isDisabled = disabled || isLoading;

    return (
      <motion.button
        ref={ref}
        whileTap={isDisabled ? undefined : { scale: 0.98 }}
        transition={{ type: 'spring', stiffness: 500, damping: 30 }}
        disabled={isDisabled}
        className={cn(
          'inline-flex items-center justify-center select-none cursor-pointer tracking-tight transition-colors',
          'focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring/50',
          'disabled:opacity-40 disabled:pointer-events-none disabled:cursor-not-allowed',
          variantStyles[variant],
          sizeStyles[size],
          className
        )}
        {...props}
      >
        {isLoading ? (
          <svg
            className="w-3.5 h-3.5 animate-spin text-current shrink-0"
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
          >
            <circle
              className="opacity-25"
              cx="12"
              cy="12"
              r="10"
              stroke="currentColor"
              strokeWidth="3"
            />
            <path
              className="opacity-75"
              fill="currentColor"
              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
            />
          </svg>
        ) : (
          leftIcon && <span className="shrink-0 leading-none">{leftIcon}</span>
        )}
        {children && <span>{children}</span>}
        {!isLoading && rightIcon && (
          <span className="shrink-0 leading-none">{rightIcon}</span>
        )}
      </motion.button>
    );
  }
);

Button.displayName = 'Button';

'use client';

import * as React from 'react';
import { motion, type HTMLMotionProps } from 'framer-motion';
import { cn } from '@/lib/utils';

export type IconButtonVariant = 'default' | 'secondary' | 'outline' | 'ghost';
export type IconButtonSize = 'sm' | 'md' | 'lg';

export interface IconButtonProps extends Omit<HTMLMotionProps<'button'>, 'children'> {
  icon: React.ReactNode;
  'aria-label': string;
  variant?: IconButtonVariant;
  size?: IconButtonSize;
  isActive?: boolean;
  shape?: 'rounded' | 'circle';
}

const variantStyles: Record<IconButtonVariant, string> = {
  default:
    'bg-primary text-primary-foreground hover:opacity-90 active:opacity-95 shadow-2xs',
  secondary:
    'bg-card border border-border text-text-primary hover:bg-accent hover:border-foreground/20 shadow-2xs',
  outline:
    'bg-transparent border border-border text-text-secondary hover:text-text-primary hover:bg-secondary/60 hover:border-foreground/20',
  ghost:
    'bg-transparent text-text-muted hover:text-text-primary hover:bg-secondary/60',
};

const sizeStyles: Record<IconButtonSize, string> = {
  sm: 'w-7 h-7 p-1 text-xs',
  md: 'w-8 h-8 p-1.5 text-sm',
  lg: 'w-10 h-10 p-2 text-base',
};

export const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  (
    {
      className,
      icon,
      'aria-label': ariaLabel,
      variant = 'ghost',
      size = 'md',
      isActive = false,
      shape = 'rounded',
      disabled,
      ...props
    },
    ref
  ) => {
    return (
      <motion.button
        ref={ref}
        whileHover={disabled ? undefined : { scale: 1.04 }}
        whileTap={disabled ? undefined : { scale: 0.95 }}
        transition={{ type: 'spring', stiffness: 400, damping: 25 }}
        aria-label={ariaLabel}
        disabled={disabled}
        className={cn(
          'inline-flex items-center justify-center cursor-pointer select-none transition-colors shrink-0',
