export interface TextareaProps extends React.TextareaHTMLAttributes<HTMLTextAreaElement> {
  hasError?: boolean;
}

export const Textarea = React.forwardRef<HTMLTextAreaElement, TextareaProps>(
  ({ className, hasError, disabled, rows = 3, ...props }, ref) => {
    return (
      <textarea
        ref={ref}
        rows={rows}
        disabled={disabled}
        className={cn(
          'w-full rounded-lg bg-card border border-border px-3 py-2.5 text-ui text-text-primary placeholder:text-text-muted/70 transition-colors',
          'hover:border-foreground/20 focus:outline-none focus:border-foreground/40 focus:ring-1 focus:ring-ring/40',
          'disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:border-border',
          hasError && 'border-destructive/60 focus:border-destructive focus:ring-destructive/30',
          className
        )}
        {...props}
      />
    );
  }
);

Textarea.displayName = 'Textarea';

import * as React from 'react';
import { cn } from '@/lib/utils';

export type BadgeVariant = 'default' | 'secondary' | 'outline' | 'mono' | 'status' | 'engraved' | 'tactile';
export type BadgeStatus = 'neutral' | 'success' | 'warning' | 'error';

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: BadgeVariant;
  status?: BadgeStatus;
  children: React.ReactNode;
}

const statusDotColors: Record<BadgeStatus, string> = {
  neutral: 'bg-text-muted',
  success: 'bg-emerald-500',
  warning: 'bg-amber-500',
  error: 'bg-rose-500',
};

export function Badge({
  className,
  variant = 'default',
  status = 'neutral',
  children,
  ...props
}: BadgeProps) {
  if (variant === 'engraved') {
    return (
      <span
        className={cn(
          'inline-flex items-center gap-1 font-mono text-[10px] uppercase tracking-wider px-2 py-0.5 rounded bg-secondary/80 text-text-muted tactile-well border border-border/40 select-none',
          className
        )}
        {...props}
      >
        {children}
      </span>
    );
  }

  if (variant === 'tactile') {
    return (
      <span
        className={cn(
          'inline-flex items-center gap-1 text-[11px] font-medium px-2.5 py-0.5 rounded-md bg-card text-text-primary tactile-surface border border-border/60 select-none',
          className
        )}
        {...props}
      >
        {children}
      </span>
    );
  }

  if (variant === 'mono') {
    return (
      <span
        className={cn(
          'inline-flex items-center gap-1 font-mono text-[10px] uppercase tracking-wider px-2 py-0.5 rounded bg-muted text-text-muted border border-border/50 select-none',
          className
        )}
        {...props}
      >
        {children}
      </span>
    );
  }

  if (variant === 'outline') {
    return (
      <span
        className={cn(
          'inline-flex items-center gap-1 text-[11px] font-medium px-2 py-0.5 rounded-md border border-border text-text-muted select-none bg-transparent',
          className
        )}
        {...props}
      >
        {children}
      </span>
    );
  }

  if (variant === 'status') {
    return (
      <span
        className={cn(
          'inline-flex items-center gap-1.5 text-[11px] font-medium px-2.5 py-0.5 rounded-full bg-secondary/80 text-text-primary border border-border/60 select-none',
          className
        )}
        {...props}
      >
        <span className={cn('w-1.5 h-1.5 rounded-full shrink-0', statusDotColors[status])} />
        <span>{children}</span>
      </span>
    );
  }

  if (variant === 'secondary') {
    return (
      <span
        className={cn(
          'inline-flex items-center gap-1 text-[11px] px-2.5 py-0.5 rounded-md bg-secondary text-text-muted border border-border/50 select-none font-medium',
          className
        )}
        {...props}
      >
        {children}
      </span>
    );
  }

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 text-sidebar-category px-2.5 py-0.5 rounded-md bg-secondary text-text-secondary border border-border/60 select-none',
        className
      )}
      {...props}
    >
      {children}
    </span>
  );
}

import * as React from 'react';
import { cn } from '@/lib/utils';

export interface SeparatorProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: 'horizontal' | 'vertical';
  decorative?: boolean;
}

export function Separator({
  className,
  orientation = 'horizontal',
  decorative = true,
  ...props
}: SeparatorProps) {
  return (
    <div
      role={decorative ? 'none' : 'separator'}
      aria-orientation={orientation}
      className={cn(
        'shrink-0 bg-border/80',
        orientation === 'horizontal' ? 'h-px w-full' : 'h-full w-px',
        className
      )}
      {...props}
    />
  );
}

import * as React from 'react';
import { cn } from '@/lib/utils';

export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  hoverable?: boolean;
  variant?: 'default' | 'tactile' | 'recessed';
}

export function Card({ className, hoverable = true, variant = 'default', ...props }: CardProps) {
  const variantClasses = {
    default: 'bg-card border border-border',
    tactile: 'bg-card border border-border/80 tactile-surface',
    recessed: 'bg-secondary/70 border border-border/60 tactile-well',
  };

  return (
    <div
      className={cn(
        'rounded-xl p-5 transition-all',
        variantClasses[variant],
        hoverable && variant === 'default' && 'hover:border-foreground/20',
        hoverable && variant === 'tactile' && 'hover:border-foreground/30 shadow-xs',
        className
      )}
      {...props}
    />
  );
}

export function CardHeader({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('flex flex-col space-y-1.5 mb-3', className)} {...props} />;
}

export function CardTitle({
  className,
  ...props
}: React.HTMLAttributes<HTMLHeadingElement>) {
  return (
    <h3
      className={cn('text-component-title text-text-primary font-medium tracking-tight', className)}
      {...props}
    />
  );
}

export function CardDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cn('text-body text-text-muted leading-relaxed', className)}
      {...props}
    />
  );
}

export function CardContent({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('text-body text-text-secondary', className)} {...props} />;
}

export function CardFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn('pt-4 mt-4 border-t border-border/60 flex items-center', className)}
      {...props}
    />
  );
}

'use client';

import * as React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';

export interface NavItem {
  id: string;
  label: string;
  href: string;
  isExternal?: boolean;
}

export interface NavbarProps {
  brand?: React.ReactNode;
  items: NavItem[];
  actions?: React.ReactNode;
  searchSlot?: React.ReactNode;
  className?: string;
}

export function Navbar({ brand, items, actions, searchSlot, className }: NavbarProps) {
  const pathname = usePathname();
  const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);

  React.useEffect(() => {
    setMobileMenuOpen(false);
  }, [pathname]);

  return (
    <header
      className={cn(
        'fixed top-0 left-0 right-0 z-50 h-12 sm:h-13 border-b border-border/70 bg-background/80 backdrop-blur-md transition-colors',
        className
      )}
    >
      <div className="max-w-6xl mx-auto h-full px-4 sm:px-6 flex items-center justify-between gap-4">
        {/* Left: Brand Identity */}
        <div className="flex items-center gap-3 shrink-0">
          {brand}
        </div>

        {/* Center: Sleek Desktop Navigation */}
        <nav className="hidden md:flex items-center gap-1">
          <ul className="flex items-center gap-1 m-0 p-0 list-none text-xs">
            {items.map((item) => {
              const isActive =
                pathname === item.href || (item.href !== '/' && pathname.startsWith(item.href));
              return (
                <li key={item.id}>
                  <Link
                    href={item.href}
                    target={item.isExternal ? '_blank' : undefined}
                    rel={item.isExternal ? 'noopener noreferrer' : undefined}
                    className={cn(
                      'px-3 py-1.5 rounded-md transition-colors font-medium select-none',
                      isActive
                        ? 'text-text-primary bg-secondary/80'
                        : 'text-text-muted hover:text-text-primary hover:bg-secondary/40'
                    )}
                  >
                    {item.label}
                  </Link>
                </li>
              );
            })}
          </ul>
        </nav>

        {/* Right: Search Omnibar + Action Cluster */}
        <div className="hidden sm:flex items-center gap-2 shrink-0">
          {searchSlot}
          {actions}
        </div>

        {/* Mobile Hamburger Trigger */}
        <div className="flex sm:hidden items-center gap-1">
          {actions}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="p-1.5 rounded-md text-text-muted hover:text-text-primary hover:bg-secondary transition-colors cursor-pointer"
            aria-label="Toggle navigation menu"
            aria-expanded={mobileMenuOpen}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              {mobileMenuOpen ? (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M6 18L18 6M6 6l12 12" />
              ) : (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 6h16M4 12h16M4 18h16" />
              )}
            </svg>
          </button>
        </div>
      </div>

      {/* Mobile Drawer */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, y: -6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -6 }}
            transition={{ duration: 0.15 }}
            className="sm:hidden border-b border-border/80 bg-background/95 backdrop-blur-xl px-4 py-3 space-y-2 shadow-lg"
          >
            {searchSlot && <div className="mb-2">{searchSlot}</div>}
            <div className="flex flex-col space-y-0.5">
              {items.map((item) => {
                const isActive =
                  pathname === item.href || (item.href !== '/' && pathname.startsWith(item.href));
                return (
                  <Link
                    key={item.id}
                    href={item.href}
                    className={cn(
                      'px-3 py-2 rounded-md text-xs font-medium transition-colors',
                      isActive
                        ? 'bg-secondary text-text-primary'
                        : 'text-text-muted hover:text-text-primary hover:bg-secondary/40'
                    )}
                  >
                    {item.label}
                  </Link>
                );
              })}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}

'use client';

import * as React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { cn } from '@/lib/utils';

export interface SidebarItem {
  id: string;
  label: string;
  href: string;
  badge?: string;
  isExternal?: boolean;
}

export interface SidebarGroup {
  title: string;
  items: SidebarItem[];
}

export interface SidebarProps extends React.HTMLAttributes<HTMLElement> {
  groups: SidebarGroup[];
  header?: React.ReactNode;
  footer?: React.ReactNode;
}

export function Sidebar({ groups, header, footer, className, ...props }: SidebarProps) {
  const pathname = usePathname();

  return (
    <aside
      className={cn(
        'w-64 shrink-0 flex flex-col justify-between py-6 px-4 bg-background border-r border-border/80 min-h-[calc(100vh-4rem)]',
        className
      )}
      {...props}
    >
      <div className="space-y-6">
        {header && <div className="mb-4 px-2">{header}</div>}

        {groups.map((group, idx) => (
          <div key={idx} className="space-y-1.5">
            <h4 className="text-sidebar-category text-text-muted uppercase tracking-wider px-2 font-medium">
              {group.title}
            </h4>
            <ul className="space-y-0.5 m-0 p-0 list-none">
              {group.items.map((item) => {
                const isActive = pathname === item.href;
                return (
                  <li key={item.id}>
                    <Link
                      href={item.href}
                      target={item.isExternal ? '_blank' : undefined}
                      rel={item.isExternal ? 'noopener noreferrer' : undefined}
                      className={cn(
                        'flex items-center justify-between px-2.5 py-1.5 rounded-lg text-ui transition-colors cursor-pointer',
                        isActive
                          ? 'bg-sidebar-accent text-text-primary font-medium border border-sidebar-border/40'
                          : 'text-text-secondary hover:text-text-primary hover:bg-sidebar-accent/50'
                      )}
                    >
                      <span className="truncate">{item.label}</span>
                      {item.badge && (
                        <span className="font-mono text-[10px] px-1.5 py-0.5 rounded bg-muted text-text-muted">
                          {item.badge}
                        </span>
                      )}
                    </Link>
                  </li>
                );
              })}
            </ul>
          </div>
        ))}
      </div>

      {footer && <div className="pt-4 border-t border-border/60 px-2">{footer}</div>}
    </aside>
  );
}

'use client';

import * as React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';

export interface TooltipProps {
  content: React.ReactNode;
  children: React.ReactNode;
  side?: 'top' | 'bottom' | 'left' | 'right';
  delay?: number;
  className?: string;
}

export function Tooltip({
  content,
  children,
  side = 'top',
  delay = 150,
  className,
}: TooltipProps) {
  const [isVisible, setIsVisible] = React.useState(false);
  const timeoutRef = React.useRef<NodeJS.Timeout | null>(null);

  const show = () => {
    timeoutRef.current = setTimeout(() => {
      setIsVisible(true);
    }, delay);
  };

  const hide = () => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setIsVisible(false);
  };

  const sidePositions: Record<string, string> = {
    top: 'bottom-full left-1/2 -translate-x-1/2 mb-2',
    bottom: 'top-full left-1/2 -translate-x-1/2 mt-2',
    left: 'right-full top-1/2 -translate-y-1/2 mr-2',
    right: 'left-full top-1/2 -translate-y-1/2 ml-2',
  };

  return (
    <div
      className="relative inline-flex"
      onMouseEnter={show}
      onMouseLeave={hide}
      onFocus={show}
      onBlur={hide}
    >
      {children}
      <AnimatePresence>
        {isVisible && (
          <motion.div
            initial={{ opacity: 0, scale: 0.96 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.96 }}
            transition={{ duration: 0.15, ease: [0.16, 1, 0.3, 1] }}
            role="tooltip"
            className={cn(
              'absolute z-50 pointer-events-none whitespace-nowrap',
              'px-2.5 py-1 rounded-md text-[11px] font-medium tracking-tight',
              'bg-foreground text-background shadow-lg shadow-black/10 dark:shadow-black/40',
              sidePositions[side],
              className
            )}
          >
            {content}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import * as React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';

interface DropdownContextType {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  close: () => void;
}

const DropdownContext = React.createContext<DropdownContextType | undefined>(undefined);

export function Dropdown({ children }: { children: React.ReactNode }) {
  const [isOpen, setIsOpen] = React.useState(false);
  const containerRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        setIsOpen(false);
      }
    }
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      document.addEventListener('keydown', handleKeyDown);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen]);

  const close = React.useCallback(() => setIsOpen(false), []);

  return (
    <DropdownContext.Provider value={{ isOpen, setIsOpen, close }}>
      <div ref={containerRef} className="relative inline-block text-left">
        {children}
      </div>
    </DropdownContext.Provider>
  );
}

export function DropdownTrigger({
  children,
  asChild,
  className,
}: {
  children: React.ReactNode;
  asChild?: boolean;
  className?: string;
}) {
  const context = React.useContext(DropdownContext);
  if (!context) throw new Error('DropdownTrigger must be used within Dropdown');

  const handleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    context.setIsOpen(!context.isOpen);
  };

  if (React.isValidElement(children)) {
    const child = children as React.ReactElement<any>;
    return React.cloneElement(child, {
      onClick: (e: React.MouseEvent) => {
        child.props?.onClick?.(e);
        handleClick(e);
      },
      'aria-haspopup': 'menu',
      'aria-expanded': context.isOpen,
    });
  }

  return (
    <button
      type="button"
      onClick={handleClick}
      aria-haspopup="menu"
      aria-expanded={context.isOpen}
      className={cn('inline-flex items-center cursor-pointer', className)}
    >
      {children}
    </button>
  );
}

export function DropdownContent({
  children,
  align = 'right',
  className,
}: {
  children: React.ReactNode;
  align?: 'left' | 'right' | 'center';
  className?: string;
}) {
  const context = React.useContext(DropdownContext);
  if (!context) throw new Error('DropdownContent must be used within Dropdown');

  const alignmentClass =
    align === 'right'
      ? 'right-0'
      : align === 'center'
      ? 'left-1/2 -translate-x-1/2'
      : 'left-0';

  return (
    <AnimatePresence>
      {context.isOpen && (
        <motion.div
          initial={{ opacity: 0, scale: 0.96, y: 4 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.96, y: 4 }}
          transition={{ duration: 0.15, ease: [0.16, 1, 0.3, 1] }}
          role="menu"
          className={cn(
            'absolute top-full mt-2 min-w-48 z-50 p-1.5',
            'bg-popover/95 backdrop-blur-2xl border border-border rounded-xl',
            'shadow-xl shadow-black/10 dark:shadow-black/60 overflow-visible space-y-0.5',
            alignmentClass,
            className
          )}
        >
          {children}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

export function DropdownItem({
  children,
  onClick,
  icon,
  shortcut,
  destructive = false,
  className,
}: {
  children: React.ReactNode;
  onClick?: () => void;
  icon?: React.ReactNode;
  shortcut?: string;
  destructive?: boolean;
  className?: string;
}) {
  const context = React.useContext(DropdownContext);

  const handleClick = (e: React.MouseEvent) => {
    if (onClick) onClick();
    if (context) context.close();
  };

  return (
    <button
      type="button"
      role="menuitem"
      onClick={handleClick}
      className={cn(
        'w-full flex items-center justify-between px-2.5 py-1.5 rounded-lg text-ui text-left transition-colors cursor-pointer select-none',
        destructive
          ? 'text-destructive hover:bg-destructive/10'
          : 'text-text-secondary hover:text-text-primary hover:bg-secondary',
        className
      )}
    >
      <div className="flex items-center gap-2 truncate">
        {icon && <span className="text-text-muted shrink-0">{icon}</span>}
        <span className="truncate">{children}</span>
      </div>
      {shortcut && (
        <span className="font-mono text-[10px] text-text-muted shrink-0 pl-2">
          {shortcut}
        </span>
      )}
    </button>
  );
}

export function DropdownSeparator({ className }: { className?: string }) {
  return <div className={cn('h-px bg-border/60 my-1 mx-1', className)} />;
}

export function DropdownLabel({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div
      className={cn(
        'px-2.5 py-1 text-[10px] uppercase font-mono tracking-wider text-text-muted font-medium select-none',
        className
