  nodes?: MetricNodePoint[];
  initialActiveIndex?: number;
  onMoreClick?: () => void;
  onPeriodClick?: () => void;
}

const DEFAULT_METRIC_NODES: MetricNodePoint[] = [
  { label: 'Jan', value: 78, tooltipValue: '$2,352.96 income', tooltipSubtext: '+12% from last month' },
  { label: 'Feb', value: 45, tooltipValue: '$1,420.10 income', tooltipSubtext: '-8% from last month' },
  { label: 'Mar', value: 38, tooltipValue: '$1,190.50 income', tooltipSubtext: '-5% from last month' },
  { label: 'Apr', value: 48, tooltipValue: '$1,520.00 income', tooltipSubtext: '+4% from last month' },
  { label: 'May', value: 68, tooltipValue: '$2,140.00 income', tooltipSubtext: '+10% from last month' },
  { label: 'Jun', value: 62, tooltipValue: '$1,980.20 income', tooltipSubtext: '+2% from last month' },
  { label: 'Jul', value: 92, tooltipValue: '$3,150.80 income', tooltipSubtext: '+18% from last month' },
];

export const TactileMetricCard = React.forwardRef<HTMLDivElement, TactileMetricCardProps>(
  (
    {
      className,
      title = 'Balance',
      periodLabel = '2023',
      accentColor = 'emerald',
      value = '$94,127',
      deltaText = 'increase 13%',
      deltaSubtext = 'vs last year',
      nodes = DEFAULT_METRIC_NODES,
      initialActiveIndex = 0,
      onMoreClick,
      onPeriodClick,
      ...props
    },
    ref
  ) => {
    const [activeIndex, setActiveIndex] = React.useState(initialActiveIndex);

    const width = 340;
    const height = 130;
    const paddingX = 18;
    const paddingY = 16;

    const points = nodes.map((node, i) => {
      const x = paddingX + (i / (nodes.length - 1)) * (width - paddingX * 2);
      const y = height - paddingY - (node.value / 100) * (height - paddingY * 2);
      return { x, y, node };
    });

    const pathD = points.reduce((acc, pt, i) => {
      return i === 0 ? `M ${pt.x},${pt.y}` : `${acc} L ${pt.x},${pt.y}`;
    }, '');

    const activePoint = points[activeIndex] || points[0];

    return (
      <div
        ref={ref}
        className={cn(
          'relative w-full max-w-sm rounded-[24px] border border-border/80 bg-[#161617] text-white p-6',
          'shadow-2xl select-none transition-all overflow-hidden',
          className
        )}
        {...props}
      >
        {/* Header: Icon + Title & Dropdown Pill + More Button */}
        <div className="flex items-center justify-between gap-3 pb-5">
          <div className="flex items-center gap-2.5">
            <div className="w-7 h-7 rounded-lg bg-white/[0.08] border border-white/10 flex items-center justify-center text-white/80">
              <BarChart2 className="w-3.5 h-3.5" />
            </div>
            <span className="text-sm font-medium tracking-tight text-white/90">{title}</span>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={onPeriodClick}
              className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-mono bg-white/[0.05] border border-white/[0.08] text-white/80 hover:bg-white/[0.08] transition-colors cursor-pointer"
            >
              <span>{periodLabel}</span>
              <ChevronDown className="w-3 h-3 text-white/40" />
            </button>
            <button
              type="button"
              onClick={onMoreClick}
              aria-label="More options"
              className="w-7 h-7 rounded-lg inline-flex items-center justify-center text-white/40 hover:text-white/80 hover:bg-white/5 transition-colors cursor-pointer"
            >
              <MoreHorizontal className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Metric Value Row */}
        <div className="flex items-center gap-3 pb-6">
          <div
            className={cn(
              'w-1 h-8 rounded-full',
              accentColor === 'emerald' && 'bg-emerald-400 shadow-sm shadow-emerald-400/40',
              accentColor === 'amber' && 'bg-amber-400 shadow-sm shadow-amber-400/40',
              accentColor === 'neutral' && 'bg-white/80'
            )}
          />
          <div className="text-3xl font-medium tracking-tight text-white">{value}</div>
          <div className="text-[11px] font-mono leading-tight text-white/50 pl-1">
            <div className="text-white/80 font-medium">{deltaText}</div>
            <div>{deltaSubtext}</div>
          </div>
        </div>

        {/* Chart Canvas Area */}
        <div className="relative w-full pt-1 pb-1">
          {/* Active Tooltip Pill */}
          {activePoint.node.tooltipValue && (
            <motion.div
              key={activeIndex}
              initial={{ opacity: 0, y: -4 }}
              animate={{ opacity: 1, y: 0 }}
              className="absolute z-20 px-3 py-1.5 rounded-xl bg-[#0d0e0f]/95 border border-white/10 text-white shadow-xl pointer-events-none"
              style={{
                left: `${Math.min(Math.max(activePoint.x - 60, 10), width - 150)}px`,
                top: `${Math.max(activePoint.y - 48, 0)}px`,
              }}
            >
              <div className="text-[11px] font-mono font-medium text-white/95">
                {activePoint.node.tooltipValue}
              </div>
              {activePoint.node.tooltipSubtext && (
                <div className="text-[10px] font-mono text-emerald-400">
                  {activePoint.node.tooltipSubtext}
                </div>
              )}
            </motion.div>
          )}

          <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-32 overflow-visible">
            {/* Active Vertical Glow Beam */}
            <rect
              x={activePoint.x - 14}
              y={0}
              width={28}
              height={height}
              rx={12}
              fill="url(#columnGlow)"
              className="transition-all duration-300 pointer-events-none"
            />

            <defs>
              <linearGradient id="columnGlow" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#10b981" stopOpacity="0.22" />
                <stop offset="100%" stopColor="#10b981" stopOpacity="0.0" />
              </linearGradient>
            </defs>

            {/* Line Trajectory */}
            <path
              d={pathD}
              fill="none"
              stroke="#10b981"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />

            {/* Interactive Node Dots */}
            {points.map((pt, i) => {
              const isActive = activeIndex === i;
              return (
                <g key={i} className="cursor-pointer" onClick={() => setActiveIndex(i)}>
                  <circle
                    cx={pt.x}
                    cy={pt.y}
                    r={isActive ? 4.5 : 3}
                    fill={isActive ? '#10b981' : '#161617'}
                    stroke="#10b981"
                    strokeWidth={isActive ? 2 : 1.5}
                    className="transition-all duration-200"
                  />
                  {isActive && (
                    <circle
                      cx={pt.x}
                      cy={pt.y}
                      r="9"
                      fill="none"
                      stroke="#10b981"
                      strokeWidth="1"
                      strokeOpacity="0.4"
                    />
                  )}
                </g>
              );
            })}
          </svg>

          {/* Month Labels */}
          <div className="flex items-center justify-between text-[11px] font-mono text-white/40 pt-2 px-1">
            {nodes.map((n, i) => (
              <button
                key={i}
                type="button"
                onClick={() => setActiveIndex(i)}
                className={cn(
                  'transition-colors cursor-pointer hover:text-white',
                  activeIndex === i ? 'text-white font-medium' : 'text-white/40'
                )}
              >
                {n.label}
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }
);

TactileMetricCard.displayName = 'TactileMetricCard';

// ─── 2. TACTILE BAR CARD (INCOME & THRESHOLD LINE) ──────────────────────────

export interface BarMetricPoint {
